//! Embed the application icon into the Windows exe (RT_ICON + RT_GROUP_ICON).
//!
//! The .res object file is generated by hand — no rc.exe / windres needed, so
//! the build stays toolchain-only (zero external crates). Only MSVC targets
//! link the resource; other targets skip it entirely.

use std::env;
use std::fs;
use std::path::PathBuf;

fn align4(n: usize) -> usize {
    (n + 3) & !3
}

/// Write one .res resource: header + data, 4-byte aligned.
fn push_res(out: &mut Vec<u8>, res_type: u16, res_id: u16, data: &[u8], lang: u16) {
    // type/name as ordinals: 0xFFFF marker + id
    let mut head = Vec::new();
    head.extend_from_slice(&0u32.to_le_bytes()); // DataSize (patched below)
    head.extend_from_slice(&0u32.to_le_bytes()); // HeaderSize (patched below)
    head.extend_from_slice(&0xffffu16.to_le_bytes());
    head.extend_from_slice(&res_type.to_le_bytes());
    head.extend_from_slice(&0xffffu16.to_le_bytes());
    head.extend_from_slice(&res_id.to_le_bytes());
    while head.len() % 4 != 0 {
        head.push(0);
    }
    head.extend_from_slice(&0u32.to_le_bytes()); // DataVersion
    head.extend_from_slice(&0x0030u16.to_le_bytes()); // MemoryFlags: MOVEABLE|DISCARDABLE
    head.extend_from_slice(&lang.to_le_bytes()); // LanguageId
    head.extend_from_slice(&0u32.to_le_bytes()); // Version
    head.extend_from_slice(&0u32.to_le_bytes()); // Characteristics
    let header_size = head.len() as u32;
    head[0..4].copy_from_slice(&(data.len() as u32).to_le_bytes());
    head[4..8].copy_from_slice(&header_size.to_le_bytes());
    out.extend_from_slice(&head);
    out.extend_from_slice(data);
    while out.len() % 4 != 0 {
        out.push(0);
    }
}

fn main() {
    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    if target_os != "windows" || target_env != "msvc" {
        return;
    }
    let ico_path = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap()).join("../app/icons/icon.ico");
    println!("cargo:rerun-if-changed={}", ico_path.display());
    let Ok(ico) = fs::read(&ico_path) else {
        println!("cargo:warning=icon.ico not found — exe will have no icon");
        return;
    };
    if ico.len() < 6 {
        return;
    }
    let count = u16::from_le_bytes([ico[4], ico[5]]) as usize;
    if count == 0 || ico.len() < 6 + count * 16 {
        return;
    }

    // .res file: null header + RT_ICON (id 1..n) + RT_GROUP_ICON (id 1)
    let mut res: Vec<u8> = Vec::new();
    res.extend_from_slice(&[0u8; 8]); // null resource (alignment)

    let mut entries: Vec<(u8, u8, u16, u16, u32, u16, u16)> = Vec::new(); // w,h,planes,bitcount,bytes,id,reserved
    for i in 0..count {
        let e = 6 + i * 16;
        let w = ico[e];
        let h = ico[e + 1];
        let planes = u16::from_le_bytes([ico[e + 4], ico[e + 5]]);
        let bitcount = u16::from_le_bytes([ico[e + 6], ico[e + 7]]);
        let size = u32::from_le_bytes([ico[e + 8], ico[e + 9], ico[e + 10], ico[e + 11]]);
        let off = u32::from_le_bytes([ico[e + 12], ico[e + 13], ico[e + 14], ico[e + 15]]) as usize;
        if off + size as usize > ico.len() {
            continue;
        }
        let img = &ico[off..off + size as usize];
        let id = (i + 1) as u16;
        push_res(&mut res, 3 /* RT_ICON */, id, img, 0x0409);
        entries.push((w, h, planes, bitcount, size, id, 0));
    }
    if entries.is_empty() {
        return;
    }

    // RT_GROUP_ICON: GRPICONDIR + GRPICONDIRENTRY per image
    let mut grp: Vec<u8> = Vec::new();
    grp.extend_from_slice(&0u16.to_le_bytes()); // reserved
    grp.extend_from_slice(&1u16.to_le_bytes()); // type = icon
    grp.extend_from_slice(&(entries.len() as u16).to_le_bytes());
    for (w, h, planes, bitcount, bytes, id, _) in &entries {
        grp.push(*w);
        grp.push(*h);
        grp.push(0); // color count
        grp.push(0); // reserved
        grp.extend_from_slice(&planes.to_le_bytes());
        grp.extend_from_slice(&bitcount.to_le_bytes());
        grp.extend_from_slice(&bytes.to_le_bytes());
        grp.extend_from_slice(&id.to_le_bytes());
    }
    push_res(&mut res, 14 /* RT_GROUP_ICON */, 1, &grp, 0x0409);

    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    let res_path = out_dir.join("app.res");
    fs::write(&res_path, &res).expect("write app.res");
    println!("cargo:rustc-link-arg-bins={}", res_path.display());
}
